from __future__ import annotations

import hashlib
import json
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any


VIEW_MODES = {"debug", "presentation"}
DISPLAY_BACKGROUNDS = {"raw", "white", "black"}
PROCESSED_BACKGROUNDS = {"white", "black"}
FOREGROUND_SCOPES = {"person", "face_near"}
MODEL_INPUTS = {"raw", "processed"}


@dataclass(frozen=True)
class InferenceSettings:
    view_mode: str = "debug"
    display_background: str = "raw"
    processed_background: str = "white"
    foreground_scope: str = "person"
    foreground_margin_ratio: float = 0.08
    detector_input: str = "processed"
    sam2_input: str = "raw"
    contact_input: str = "raw"
    protect_tracked_device: bool = True
    device_protection_margin_ratio: float = 0.10

    @classmethod
    def from_dict(cls, value: dict[str, Any]) -> "InferenceSettings":
        unknown = set(value) - set(cls.__dataclass_fields__)
        if unknown:
            raise ValueError(f"unknown inference settings: {sorted(unknown)}")
        settings = cls(**value)
        settings.validate()
        return settings

    @classmethod
    def load(cls, path: Path) -> "InferenceSettings":
        if not path.is_file():
            return cls()
        payload = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            raise ValueError("runtime inference settings must be a JSON object")
        return cls.from_dict(payload)

    def validate(self) -> None:
        enum_fields = {
            "view_mode": (self.view_mode, VIEW_MODES),
            "display_background": (self.display_background, DISPLAY_BACKGROUNDS),
            "processed_background": (self.processed_background, PROCESSED_BACKGROUNDS),
            "foreground_scope": (self.foreground_scope, FOREGROUND_SCOPES),
            "detector_input": (self.detector_input, MODEL_INPUTS),
            "sam2_input": (self.sam2_input, MODEL_INPUTS),
            "contact_input": (self.contact_input, MODEL_INPUTS),
        }
        for name, (value, allowed) in enum_fields.items():
            if value not in allowed:
                raise ValueError(f"{name} must be one of {sorted(allowed)}")
        if not 0.0 <= float(self.foreground_margin_ratio) <= 0.20:
            raise ValueError("foreground_margin_ratio must be between 0 and 0.20")
        if not 0.0 <= float(self.device_protection_margin_ratio) <= 0.25:
            raise ValueError("device_protection_margin_ratio must be between 0 and 0.25")
        if not isinstance(self.protect_tracked_device, bool):
            raise ValueError("protect_tracked_device must be boolean")

    @property
    def configuration_hash(self) -> str:
        encoded = json.dumps(asdict(self), ensure_ascii=True, sort_keys=True).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()[:12]

    def as_dict(self) -> dict[str, Any]:
        return {**asdict(self), "configuration_hash": self.configuration_hash}

    def inference_signature(self) -> tuple[object, ...]:
        return (
            self.processed_background,
            self.foreground_scope,
            round(float(self.foreground_margin_ratio), 6),
            self.detector_input,
            self.sam2_input,
            self.contact_input,
            self.protect_tracked_device,
            round(float(self.device_protection_margin_ratio), 6),
        )

    def persist(self, path: Path) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_suffix(path.suffix + ".tmp")
        temporary.write_text(
            json.dumps(asdict(self), ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        temporary.replace(path)

