class RecommendedPreprocessor:
    def __init__(self, project_root: Path) -> None:
        self.face_landmarker = mp.tasks.vision.FaceLandmarker.create_from_model_path(
            str(project_root / "models/mediapipe/face_landmarker.task")
        )
        self.person_gate = PersonForegroundGate(
            project_root / "models/mediapipe/selfie_multiclass_256x256.tflite"
        )

    def __enter__(self) -> "RecommendedPreprocessor":
        return self

    def __exit__(self, *_args: object) -> None:
        self.face_landmarker.close()
        self.person_gate.close()

    def process(self, image: Image.Image, bbox: list[float] | None) -> tuple[Image.Image, str]:
        rgb = np.ascontiguousarray(np.asarray(image.convert("RGB")))
        result = self.face_landmarker.detect(mp.Image(image_format=mp.ImageFormat.SRGB, data=rgb))
        if not result.face_landmarks:
            return image.copy(), "face_not_detected_raw_fallback"
        landmarks = [
            (float(point.x) * image.width, float(point.y) * image.height)
            for point in result.face_landmarks[0]
        ]
        gate = build_face_gate(landmarks, image.size)
        if gate is None:
            return image.copy(), "face_geometry_failed_raw_fallback"
        prepared = prepare_frame(
            image,
            gate,
            self.person_gate,
            scope="person",
            margin_ratio=0.03,
            background="white",
            protected_bbox=tuple(bbox) if bbox is not None else None,
            device_margin_ratio=0.10,
        )
        if prepared.foreground is None:
            return image.copy(), "person_segmentation_failed_raw_fallback"
        return prepared.image, "person_white"


